#include <stdio.h>

int main(void) {
    int ti_le, co_lon;
    scanf("%d %d", &ti_le, &co_lon);
    int nguong = co_lon ? 300 : 450;
    if (ti_le >= nguong) printf("dat\n");
    else printf("chua dat\n");
    return 0;
}
